<?php

declare(strict_types=1);

namespace App\Services\Ai\Data;

/**
 * Synthesised speech plus only the metadata worth persisting.
 *
 * The raw provider response is not carried out of the adapter, and callers must
 * never log the text or the audio. `filename` is always generated by the
 * server, never taken from a request or a provider.
 */
final readonly class SpeechSynthesis
{
    public function __construct(
        public string $contents,
        public string $mimeType,
        public string $filename,
        public string $format = 'ogg',
        public string $voice = '',
        public string $model = '',
        public int $latencyMs = 0,
        public ?float $durationSeconds = null,
        public ?string $providerResponseId = null,
    ) {}

    public function size(): int
    {
        return strlen($this->contents);
    }

    public function isEmpty(): bool
    {
        return trim($this->contents) === '';
    }
}
